// oa3_params.h - OA-SLAM object-association parameters exposed as environment variables.
// Generated by oa3-agent/tools/patch_params.py. Defaults below were read from the source at patch time.
// Unset variables keep the defaults, so the unpatched behaviour is reproduced exactly.
#pragma once
#include <cstdio>
#include <cstdlib>
#include <chrono>

namespace oa3 {
inline double env_double(const char* name, double def) { const char* v = std::getenv(name); return (v && *v) ? std::atof(v) : def; }
inline int    env_int(const char* name, int def)       { const char* v = std::getenv(name); return (v && *v) ? std::atoi(v) : def; }

struct Params {
    double det_score;   // detection score gate inside tracking            (OA_DET_SCORE, default 0.5)
    double iou2d;       // MIN_2D_IOU_THRESH: IoU with the track's last bbox (OA_IOU2D,     default 0.2)
    double iou3d;       // MIN_3D_IOU_THRESH: IoU with projected ellipsoid  (OA_IOU3D,     default 0.3)
    int    time_diff;   // TIME_DIFF_THRESH: frames before a track expires  (OA_TIME_DIFF, default 30)
    int    nb_match;    // THRESHOLD_NB_MATCH: shared map points            (OA_NB_MATCH,  default 10)
    int    min_obs;     // observations before ellipsoid initialisation     (OA_MIN_OBS,   default 10)
    int    map_obs;     // observations before insertion into the map       (OA_MAP_OBS,   default 40)
    Params()
        : det_score(env_double("OA_DET_SCORE", 0.5)), iou2d(env_double("OA_IOU2D", 0.2)),
          iou3d(env_double("OA_IOU3D", 0.3)), time_diff(env_int("OA_TIME_DIFF", 30)),
          nb_match(env_int("OA_NB_MATCH", 10)), min_obs(env_int("OA_MIN_OBS", 10)),
          map_obs(env_int("OA_MAP_OBS", 40)) {
        std::printf("EFFECTIVE OA_DET_SCORE=%g\nEFFECTIVE OA_IOU2D=%g\nEFFECTIVE OA_IOU3D=%g\nEFFECTIVE OA_TIME_DIFF=%d\n"
                    "EFFECTIVE OA_NB_MATCH=%d\nEFFECTIVE OA_MIN_OBS=%d\nEFFECTIVE OA_MAP_OBS=%d\n",
                    det_score, iou2d, iou3d, time_diff, nb_match, min_obs, map_obs);
        std::fflush(stdout);
    }
};
inline const Params& P() { static Params p; return p; }
}  // namespace oa3
